using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.TKT.DocumentosComentarioTicket;using GraphApi.Services.TKT.DocumentosComentarioTicket;namespace GraphApi.Controllers.TKT.DocumentosComentarioTicket{    /// <summary>    /// Gestión de DocumentosComentarioTickets: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("TKT/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre DocumentosComentarioTickets")]    public class DocumentosComentarioTicketController : Controller    {        private readonly IDocumentosComentarioTicketService _objService;        public DocumentosComentarioTicketController(IDocumentosComentarioTicketService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los DocumentosComentarioTickets, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="documentoComentarioTicketID">DocumentoComentarioTicketID</param>        /// <param name="comentarioTicketID">ComentarioTicketID</param>        /// <param name="documentoID">DocumentoID</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de DocumentosComentarioTickets</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar DocumentosComentarioTickets",            Description = "Devuelve DocumentosComentarioTickets aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadDocumentosComentarioTicket>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadDocumentosComentarioTicket>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? documentoComentarioTicketID,            [FromQuery] int? comentarioTicketID,            [FromQuery] int? documentoID,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetDocumentosComentarioTicketsDynamic(                documentoComentarioTicketID,                 comentarioTicketID,                 documentoID,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo DocumentosComentarioTicket.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del DocumentosComentarioTicket a crear.</param>        /// <returns>El DocumentosComentarioTicket recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear DocumentosComentarioTickets",            Description = "Inserta un nuevo DocumentosComentarioTicket en la base de datos."        )]        [ProducesResponseType(typeof(clReadDocumentosComentarioTicket), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadDocumentosComentarioTicket>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateDocumentosComentarioTicket objInput)        {            var vCreated = await _objService.CreateDocumentosComentarioTicket(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de DocumentosComentarioTicket.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del DocumentosComentarioTicket.</param>        /// <returns>El DocumentosComentarioTicket actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar DocumentosComentarioTickets",            Description = "Actualiza uno o varios campos de DocumentosComentarioTicket existente."        )]        [ProducesResponseType(typeof(clReadDocumentosComentarioTicket), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadDocumentosComentarioTicket>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateDocumentosComentarioTicket objInput)        {            var vUpdated = await _objService.UpdateDocumentosComentarioTicket(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un DocumentosComentarioTicket por su ID.        /// </summary>        [HttpDelete("{nDocumentosComentarioTicketID:int}")]        [SwaggerOperation(            Summary = "Eliminar DocumentosComentarioTicket",            Description = "Borra un DocumentosComentarioTicket si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nDocumentosComentarioTicketID)        {            var success = await _objService.DeleteDocumentosComentarioTicket(nDocumentosComentarioTicketID);            return success ? NoContent() : NotFound();        }    }}